/**
 * Kimi's identity on the key faces: a blue accent and a simple mark (a
 * white "K" with a blue dot) drawn with canvas primitives; no logo file.
 * Owned by the architect: implementers do not edit this file.
 */
import type { Brand, KeyMark } from '../types';

const ACCENT = '#3d8bff';
const DOT = '#1f7bff';
const GLYPH = '#fafaf9';

const kimiMark: KeyMark = {
  draw(ctx, x, y, size) {
    const s = size;
    const at = (fx: number, fy: number): [number, number] => [
      x + fx * s,
      y + fy * s,
    ];
    ctx.fillStyle = GLYPH;
    ctx.strokeStyle = GLYPH;
    // stem
    ctx.beginPath();
    ctx.roundRect(...at(0.22, 0.26), 0.15 * s, 0.56 * s, 0.03 * s);
    ctx.fill();
    // arm and leg
    ctx.lineWidth = 0.15 * s;
    ctx.lineCap = 'butt';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(...at(0.33, 0.6));
    ctx.lineTo(...at(0.66, 0.27));
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(...at(0.43, 0.5));
    ctx.quadraticCurveTo(...at(0.6, 0.62), ...at(0.7, 0.82));
    ctx.stroke();
    // the dot
    ctx.fillStyle = DOT;
    ctx.beginPath();
    ctx.arc(...at(0.78, 0.2), 0.085 * s, 0, Math.PI * 2);
    ctx.fill();
  },
};

export const KIMI_BRAND: Brand = {
  name: 'Kimi',
  productName: 'Kimi Code',
  accent: ACCENT,
  mark: kimiMark,
};
